import time
from pathlib import Path

def tail_f(path):
    with open(path) as f:
        f.seek(0, 2)
        while True:
            line = f.readline()
            if not line:
                time.sleep(0.2); continue
            yield line.rstrip('\n')

for line in tail_f('{{log_path}}'):
    print(line)
